/**
 ******************************************************************************
 * @file    brendon_battery_usb.c
 * TEAM CODE (owner: Brendon - battery monitor and USB-C MSC) - written by the BJT2 team, not generated by STM32CubeMX.
 * @brief   Battery monitoring + USB-C MSC subsystem (Brendon Bone) — PD6.
 *
 * RTOS role: BrendonTask owns I2C1 (BQ34Z100 fuel gauge, via the bq_bus port:
 * HAL_I2C_Mem_Read_IT + BRENDON_I2C_DONE_FLAG when the I2C1 IRQs are enabled,
 * blocking owner-only fallback otherwise) and the USB device state; sleeps
 * 100 ms (osDelay) at the start of every loop pass, so the charger poll and
 * the USB watch run about 10 times a second;
 * produces BatteryMsg_t on batteryQueue (newest wins, 1 Hz; its time to empty
 * / to full is our own estimate, battery_time.c), JackCmd_t and TomCmd_t;
 * numbers each USB hand-over's ENTER_MSC (JackCmd_t.seq) and takes Jack's
 * ack with that number on its own reply queue (request/response, slide 24),
 * also one that comes after the 2 s wait (usb_watch);
 * releases faultBeepSem on a rising LOW edge (slide 12) and sends
 * TOM_CMD_BATTERY_LOCKOUT when the speaker-lockout latch changes (critical
 * battery: TomTask plays the critical tune, then mutes the speaker), or
 * TOM_CMD_PLAY_TUNE(TOM_TUNE_CRITICAL) when the critical alarm sets again
 * while the lockout is still on from an earlier entry; reports faults to
 * TonyTask's fault screen (faultQueue, once per occurrence): lockout
 * engaged, gauge not found at start, gauge lost (3 bad polls in a row),
 * USB host gone after writing without ejecting; serves the debug screen:
 * drains brendonCmdQueue (SOC override, timeout 0) every loop pass and
 * publishes PowerDebugMsg_t on powerDebugQueue (newest wins, 1 Hz);
 * priority osPriorityBelowNormal; stack 768 words.
 *
 * The subsystem logic is the host-tested PD5b code (battery_monitor,
 * battery_time, charger_status, msc_store, bq34z100); this file is only the
 * RTOS glue. The serial test menu was removed with the UART on 1 Nov 2026.
 *
 * Words used here:
 *   SOC   state of charge: how full the battery is, 0..100 %, as worked out
 *         by the fuel gauge (the BQ34Z100 chip, read over I2C1).
 *   _IT + BRENDON_I2C_DONE_FLAG  start an I2C transfer, then sleep until its
 *         interrupt wakes this task with a thread flag (see brendon_ports.c).
 *   MSC   USB Mass Storage Class: the PC sees the SD card as a USB drive.
 *   SCSI  the disk commands the PC sends inside MSC (READ(10), WRITE(10),
 *         START STOP UNIT = eject).
 *   VBUS  the 5 V line of the USB cable: there only while a powered PC or
 *         charger is plugged in (read on PA9, VBUS_SENSE).
 *   PD2 req 2.20 / B9  requirement numbers from the team's Prototype Design
 *         2 (PD2) document. PD5b = the host-tested modules, PD6 = this RTOS
 *         version. "slide N" = the ZEIT4230 RTOS lecture slide whose
 *         pattern is used.
 *
 * Main steps (Brendon_TaskEntry):
 *   at start: create the private reply queue, report a missing gauge,
 *   publish the first snapshot; then loop (each pass first sleeps
 *   LOOP_PERIOD_MS = 100 ms):
 *     1. no gauge yet -> look for it again every 5 s
 *     2. debug-screen commands (brendonCmdQueue: SOC override)
 *     3. BatMon_Tick: 1 Hz gauge poll -> battery_publish (batteryQueue, LOW
 *        beep, speaker lockout, fault screen)
 *     4. Charger_Tick every 100 ms (STAT, PG, ALERT and VBUS pins)
 *     5. usb_watch: PC attached / gone -> hand the SD card over / back
 *     6. usb_gate: start / stop the USB stack from VBUS
 *     7. while the PC has the card: bring it up once (MSC_Poll)
 *     8. PowerDebugMsg_t for the debug screen every 1 s
 ******************************************************************************/
#include "brendon_battery_usb.h"
#include "brendon_ports.h"
#include "battery_monitor.h"
#include "battery_time.h"
#include "charger_status.h"
#include "msc_store.h"
#include "bq34z100.h"
#include "app_rtos.h"
#include "usbd_storage_if.h"     /* STORAGE_SD_Poll(): no longer called, the loop calls MSC_Poll() itself */
#include "main.h"                /* SD_DETECT_Pin + hsd.ErrorCode: card pulled while the host has it */
#include "usb_device.h"
#include "usbd_def.h"
#include "usbd_msc.h"            /* MSC class data: has the host ejected the medium? (read only) */

extern USBD_HandleTypeDef hUsbDeviceFS;   /* defined in usb_device.c (CubeMX) */

/* ---------------------------- module state -------------------------------*/
static Battery_Monitor     s_mon;           /* PD5b battery monitor */
static BatTime_Estimator   s_time;          /* PD5b time to empty / to full (one update per publish) */
static Charger_Monitor     s_chg;           /* PD5b charger/gauge pin decoder */
static uint8_t             s_low_prev = 0U;              /* LOW alarm at the last VALID publish (edge detection) */
static uint8_t             s_crit_prev = 0U;             /* critical alarm at the last VALID publish */
static uint8_t             s_lockout_prev = 0U;          /* lockout state TomTask was last told */
static uint8_t             s_lockout_valid_prev = 0U;    /* lockout at the last VALID publish (critical re-entry) */
static uint8_t             s_lockout_resend = 0U;        /* publishes since the lockout state was last sent */
static uint8_t             s_bad_polls = 0U;             /* invalid gauge polls in a row (gauge present) */
static uint8_t             s_gauge_lost_sent = 0U;       /* "Gauge not answering" sent; re-armed by a valid poll */

/* USB watch (usb_watch): is a PC attached, and does it have the SD card? */
static uint8_t             s_usb_configured = 0U;        /* debounced: a PC has configured us (USB_DEBOUNCE_MS) */
static uint8_t             s_usb_raw_prev = 0U;          /* last raw reading of "configured" */
static uint32_t            s_usb_change_ms = 0U;         /* tick when the raw reading last changed */
static uint8_t             s_msc_active = 0U;            /* 1 = Jack acked ENTER_MSC: the card is the PC's */
static uint8_t             s_msc_ejected = 0U;           /* host ejected the medium (last state seen while MSC active) */
/* Number of the last USB hand-over (JackCmd_t.seq of its ENTER_MSC): 1..255,
 * never 0. Jack echoes it in his ack, so an ack for an older hand-over is
 * told apart and dropped (see usb_watch). */
static uint8_t             s_msc_seq = 0U;
/* 1 = the MSC_ACK_TIMEOUT_MS wait for that ack ran out, but the ack is still
 * taken when it comes: every loop pass looks for it (msc_poll_late_ack). */
static uint8_t             s_msc_ack_late = 0U;
extern SD_HandleTypeDef    hsd;                          /* CubeMX, main.c: ErrorCode read only, no bus access */
/* 1 once MSC_Poll() has reported the card up for the host after a hand-over.
 * From then on the SDIO bus belongs to the OTG_FS ISR (raw block I/O for the
 * host) and this task must not put its own CMD13/re-init on it. */
static uint8_t             s_msc_card_up = 0U;
/* USB gate (AN4879 2.6.1 / 3.1.1): a self-powered device may connect its D+
 * pull-up only while VBUS is present, so the whole OTG_FS stack runs only
 * while VBUS_SENSE (PA9) is high. Measured on the PCB (27 Sep 2026): with the
 * stack started unconditionally and no cable, PA9 sat at ~1.8 V (10 kOhm to
 * GND) and read "VBUS present"; it was 0 V until MX_USB_DEVICE_Init ran. Path:
 * D+ pull-up (3.3 V) -> the USBLC6-2SC6's I/O-to-VBUS steering diode -> VBUS
 * net. So PA9 cannot be trusted while the stack is up: a host leaving
 * (usb_watch), or no host at all for USB_NO_HOST_MS, also stops the stack,
 * and PA9 is re-read with the stack off before a restart.
 * (D+ pull-up: the resistor inside the STM32's USB block that tells a host
 * "a device is plugged in". AN4879: ST's application note on USB hardware.) */
static uint8_t             s_usb_running = 0U;
static uint8_t             s_usb_host_left = 0U;         /* usb_watch -> usb_gate */
static uint8_t             s_vbus_raw_prev = 0U;
static uint32_t            s_vbus_change_ms = 0U;
static uint32_t            s_usb_hold_until = 0U;        /* no restart before this tick */
static uint32_t            s_usb_host_seen_ms = 0U;      /* last start, or last tick configured */
static osMessageQueueId_t  s_replyQueue = NULL;          /* JackReply_t, len 1: ENTER_MSC acks only */

#define CHARGER_POLL_MS     100U    /* Charger_Tick period: 10 Hz sees the 1 Hz STAT fault blink */
#define USB_DEBOUNCE_MS     500U    /* "PC attached" / "PC gone" must hold this long (see usb_watch) */
#define VBUS_DEBOUNCE_MS    300U    /* 3 charger polls: PA9 must hold this long */
#define USB_RESTART_HOLD_MS 1500U   /* after a stop: the VBUS net (incl. the charger's input
                                     * capacitor via the jumper) needs time to discharge */
#define USB_NO_HOST_MS      3000U   /* running this long with no configured host -> re-check PA9 */
#define MSC_ACK_TIMEOUT_MS  2000U   /* wait for Jack's ENTER_MSC ack (a later ack is still taken) */
#define LOOP_PERIOD_MS      100U    /* one loop pass every 100 ms: charger 10 Hz, USB watch, debug commands */
#define GAUGE_RETRY_MS      5000U   /* re-probe period while the gauge is absent */
#define LOCKOUT_RESEND_PUBLISHES 10U /* repeat the current lockout state every 10 publishes (~10 s) */
#define GAUGE_LOST_POLLS    3U      /* invalid polls in a row before "Gauge not answering" (~3 s) */
#define POWER_DEBUG_MS      1000U   /* PowerDebugMsg_t period (debug screen, Battery / power page) */
#define GAUGE_DK_AT_0C      2732    /* the gauge reports 0.1 K: 0 degC = 273.2 K */

/* ---------------------------- message helpers --------------------------- */
/* Commands for another owner task: put with a 10 ms timeout; if the queue
 * stays full the command is dropped and counted in g_rtos_dropped (slide 18).
 * TomTask sleeps on thread flags (its DMA interrupts wake it), not on its
 * queue, so a TomCmd_t also needs TOM_CMD_FLAG to wake it. The two commands
 * for Jack are with the USB hand-over below (send_enter_msc, send_exit_msc). */
static void send_tom(TomCmdType_t type, uint8_t value)
{
    TomCmd_t c = { .type = type, .value = value };
    (void)App_RTOS_Put(tomCmdQueue, &c, 10U, &g_rtos_dropped.tom_cmd);
    (void)osThreadFlagsSet(TomTaskHandle, TOM_CMD_FLAG);
}

/* ---------------------------- periodic work ----------------------------- */
/* Speaker lockout (PD2 req 2.20). TomTask is told when the latch changes:
 * TOM_CMD_BATTERY_LOCKOUT 1 = play the critical tune, then hold the speaker at
 * gain 0; 0 = restore the stored volume/mute. While the latch is unchanged,
 * its current state is sent again every LOCKOUT_RESEND_PUBLISHES publishes, so
 * one dropped command can neither leave the speaker on nor keep it muted after
 * the release (Tom ignores a repeat). The latch only moves on valid polls
 * (battery_monitor.c), so this needs no valid check of its own. At boot the
 * latch may already be set by BatMon_Init's first reading: the first publish
 * then takes the same "ON" path, so a critical boot sounds the tune too.
 * The rising edge is also the fault screen's "Critical charge": once per
 * lockout, not on the 10 s repeats.
 * The latch itself is in battery_monitor.c. Its hysteresis (on below 10 %,
 * off only at 32 %) means SOC noise around 10 % cannot switch the speaker
 * on and off, and the speaker comes back just as the LOW alarm ends. */
static void lockout_publish(uint8_t lockout)
{
    if (lockout && !s_lockout_prev) {
        send_tom(TOM_CMD_BATTERY_LOCKOUT, 1U);
        App_RTOS_RaiseFault(FAULT_SRC_BATTERY, FAULT_BAT_CRITICAL, "Critical charge", "Speaker muted");
        s_lockout_resend = 0U;
    } else if (!lockout && s_lockout_prev) {
        send_tom(TOM_CMD_BATTERY_LOCKOUT, 0U);
        s_lockout_resend = 0U;
    } else {
        s_lockout_resend++;
        if (s_lockout_resend >= LOCKOUT_RESEND_PUBLISHES) {
            s_lockout_resend = 0U;
            send_tom(TOM_CMD_BATTERY_LOCKOUT, lockout);     /* the current state: 1 or 0 */
        }
    }
    s_lockout_prev = lockout;
}

/* Charging flag for the Battery screen (PD2 B9). The charger's STAT pin,
 * decoded by Charger_Tick at 10 Hz, is the authority. Only while its state is
 * UNKNOWN (no good pin sample yet, e.g. at the first publish on task start,
 * or a pin read failed) does the gauge decide: positive current = charging. */
static uint8_t battery_charging(const Battery_Snapshot_t *snap)
{
    Charger_State st = Charger_GetState(&s_chg);
    if (st == CHARGER_STATE_UNKNOWN) {
        return (snap->valid && snap->current_mA > 0) ? 1U : 0U;
    }
    return (st == CHARGER_STATE_CHARGING) ? 1U : 0U;   /* NO_INPUT, COMPLETE, FAULT: not charging */
}

/* Publish the snapshot BatMon_Tick just took; fault-beep on a rising edge of
 * the LOW alarm (counting semaphore, slide 12); drive the speaker lockout.
 * Time to empty / to full are our own estimate (battery_time.c), updated once
 * per publish: RemainingCapacity and FullChargeCapacity over a 2-minute
 * average of the gauge's instant current, restarted when the charger is
 * plugged in or out, and sent as the screens show them (in steps: one step
 * once the new time is 1.5 steps away, straight there from 2.5, never
 * flicking between two). The gauge's own AverageTimeToEmpty/Full follow its slow
 * AverageCurrent (minutes to swing through zero after an unplug), so they
 * only go to the debug screen (power_debug_publish). */
static void battery_publish(void)
{
    Battery_Snapshot_t snap;
    BatTime_Result t;
    BatMon_GetSnapshot(&s_mon, &snap);
    uint8_t charging = battery_charging(&snap);
    BatTime_Update(&s_time, &snap, charging,
                   (Charger_GetState(&s_chg) == CHARGER_STATE_COMPLETE_OR_DISABLED) ? 1U : 0U, &t);
    BatteryMsg_t m = {
        .voltage_mV     = snap.voltage_mV,
        .current_mA     = snap.current_mA,         /* gauge AverageCurrent (slow) */
        .soc_pct        = snap.soc_pct,
        .valid          = snap.valid,
        .low            = BatMon_IsLowBattery(&s_mon),
        .critical       = BatMon_IsCriticalBattery(&s_mon),
        .lockout        = BatMon_IsSpeakerLockout(&s_mon),
        .charging       = charging,
        .tte_min        = t.tte_shown_min,         /* as shown: in steps, held; 65535 (no estimate) until 3 readings are averaged */
        .ttf_min        = t.ttf_shown_min,
        .current_now_mA = snap.current_now_mA,     /* 0 in an invalid snapshot (battery_monitor.c) */
        .current_avg_mA = t.avg_mA,                /* 0 when not valid */
    };
    /* Newest wins: batteryQueue holds ONE message, and App_RTOS_Publish
     * empties it and then puts with timeout 0. TonyTask always gets the
     * latest reading (an older one is worth nothing once a newer exists),
     * and this task never waits for the UI. */
    App_RTOS_Publish(batteryQueue, &m, &g_rtos_dropped.battery);

    /* Edge-detect only on valid snapshots: a transient gauge read failure
     * reports low = critical = 0 and would otherwise re-arm the edge, so the
     * next good reading would beep again. */
    if (m.valid) {
        uint8_t crit_rose = (m.critical && !s_crit_prev) ? 1U : 0U;
        if (crit_rose) {
            /* No fault beep for critical: the 520 ms critical tune replaces
             * it. A first entry plays it through the lockout below. If the
             * lockout was already on at the previous valid reading (the
             * battery only got back to 12..31 %), Tom ignores a repeated
             * "engage", so ask for the tune itself. The previous VALID
             * reading, not the previous publish: a gauge found late by the
             * re-probe can publish the lockout's rising edge on an invalid
             * reading, and that edge has already played the tune. */
            if (m.lockout && s_lockout_valid_prev) {
                send_tom(TOM_CMD_PLAY_TUNE, (uint8_t)TOM_TUNE_CRITICAL);
            }
        }
        /* A first reading already below 10 % raises low and critical in the
         * same poll: that gives the critical tune only, not a beep as well. */
        if (m.low && !s_low_prev && !crit_rose) {
            (void)osSemaphoreRelease(faultBeepSem);
        }
        s_low_prev = m.low;
        s_crit_prev = m.critical;
        s_lockout_valid_prev = m.lockout;
    }

    /* Gauge lost (fault screen): GAUGE_LOST_POLLS invalid polls in a row
     * from a gauge that did answer at some point. Sent once; the next valid
     * poll re-arms it. A missing gauge (never found) is reported once at
     * task start instead, so it is not counted here. */
    if (m.valid) {
        s_bad_polls = 0U;
        s_gauge_lost_sent = 0U;
    } else if (BatMon_GaugePresent(&s_mon)) {
        if (s_bad_polls < GAUGE_LOST_POLLS) s_bad_polls++;
        if (s_bad_polls >= GAUGE_LOST_POLLS && !s_gauge_lost_sent) {
            s_gauge_lost_sent = 1U;
            App_RTOS_RaiseFault(FAULT_SRC_BATTERY, FAULT_BAT_GAUGE_LOST, "Gauge not answering", "Battery info off");
        }
    }

    lockout_publish(m.lockout);
}

/* ---------------------------- debug screen ------------------------------ */
/* brendonCmdQueue: the debug screen's battery fault injection (TonyTask ->
 * here). Drained completely every loop pass with timeout 0, BEFORE
 * BatMon_Tick: BatMon_SetSocOverride makes that tick poll at once, so the
 * overridden SOC reaches batteryQueue (status bar, alarms, lockout) in the
 * same pass. The override itself is battery_monitor.c (host-tested).
 * A refused override (no gauge, or a SOC above 100 %) changes nothing; the
 * debug screen's override row shows what is in force. Any other command type
 * would be a programming error and is ignored. */
static void brendon_cmd_drain(uint32_t now)
{
    BrendonCmd_t c;
    while (osMessageQueueGet(brendonCmdQueue, &c, NULL, 0U) == osOK) {
        if (c.type == BRENDON_CMD_SOC_OVERRIDE) {
            (void)BatMon_SetSocOverride(&s_mon, c.soc_pct, c.seconds, now);
        }
    }
}

/* Cell temperature for the debug page in 0.1 degC: ONE Temperature() read
 * per publish, and only while the gauge is present (a missing gauge would
 * only give a failed transfer). INT16_MIN = unknown. */
static int16_t power_debug_temp_dC(void)
{
    uint16_t dK = 0U;
    if (!BatMon_GaugePresent(&s_mon) ||
        BQ34Z100_ReadTemperature_dK(BrendonPorts_BqBus(), &dK) != BQ_OK) {
        return INT16_MIN;
    }
    int32_t dC = (int32_t)dK - GAUGE_DK_AT_0C;
    return (dC > INT16_MAX) ? INT16_MAX : (int16_t)dC;   /* a garbage 0xFFFF must not wrap negative */
}

/* PowerDebugMsg_t for the debug screen's Battery / power page, every
 * POWER_DEBUG_MS whether or not the gauge answers (the charger and USB lines
 * matter most when it does not). Built only from what this task owns: the
 * last snapshot and latches, the override, the charger decoder, the USB gate
 * and watch, the USB device state. TonyTask never touches I2C1, the charger
 * pins or the USB stack. */
static void power_debug_publish(uint32_t now)
{
    Battery_Snapshot_t snap;
    BatMon_GetSnapshot(&s_mon, &snap);
    int16_t temp_dC = power_debug_temp_dC();          /* the only gauge transfer here */
    PowerDebugMsg_t m = {
        .voltage_mV      = snap.voltage_mV,
        .current_mA      = snap.current_mA,
        .soc_pct         = snap.soc_pct,              /* with a debug override applied */
        .soc_override    = BatMon_SocOverrideActive(&s_mon),
        .override_left_s = BatMon_SocOverrideSecondsLeft(&s_mon, now),
        .tte_min         = snap.tte_min,              /* the gauge's own (slow) estimate, */
        .ttf_min         = snap.ttf_min,              /* not BatteryMsg_t's battery_time one */
        .temp_dC         = temp_dC,
        .gauge_present   = BatMon_GaugePresent(&s_mon),
        .valid           = snap.valid,
        .charger_state   = (uint8_t)Charger_GetState(&s_chg),
        .power_good      = Charger_IsPowerGood(&s_chg),
        .vbus            = Charger_IsVbusPresent(&s_chg),
        .usb_running     = s_usb_running,
        .usb_state       = hUsbDeviceFS.dev_state,
        .msc_active      = s_msc_active,
        .low             = BatMon_IsLowBattery(&s_mon),
        .critical        = BatMon_IsCriticalBattery(&s_mon),
        .lockout         = BatMon_IsSpeakerLockout(&s_mon),
        .i2c_irq         = BrendonPorts_I2cIsInterruptDriven(),
    };
    App_RTOS_Publish(powerDebugQueue, &m, &g_rtos_dropped.power_debug);   /* newest wins, like batteryQueue */
}

/* ------------------------- USB hand-over (MSC) -------------------------- */
/* The number for the next hand-over: 1..255, skipping 0 (0 = not numbered). */
static uint8_t next_msc_seq(void)
{
    s_msc_seq++;
    if (s_msc_seq == 0U) {
        s_msc_seq = 1U;
    }
    return s_msc_seq;
}

/* ENTER_MSC carrying this hand-over's number; Jack's ack (with the same
 * number) comes back on s_replyQueue. */
static void send_enter_msc(uint8_t seq)
{
    JackCmd_t c = { .type = JACK_CMD_ENTER_MSC, .index = 0U, .seconds = 0U, .seq = seq,
                    .replyQueue = s_replyQueue };
    (void)App_RTOS_Put(jackCmdQueue, &c, 10U, &g_rtos_dropped.jack_cmd);
}

/* EXIT_MSC: the host has gone, Jack mounts the card again. No reply. */
static void send_exit_msc(void)
{
    JackCmd_t c = { .type = JACK_CMD_EXIT_MSC, .index = 0U, .seconds = 0U, .seq = 0U,
                    .replyQueue = NULL };
    (void)App_RTOS_Put(jackCmdQueue, &c, 10U, &g_rtos_dropped.jack_cmd);
}

/* 1 if this reply is the ack for the ENTER_MSC sent last. */
static uint8_t msc_ack_matches(const JackReply_t *r)
{
    return (r->type == JACK_CMD_ENTER_MSC && r->seq == s_msc_seq) ? 1U : 0U;
}

/* Wait up to MSC_ACK_TIMEOUT_MS for the ack of the ENTER_MSC sent last
 * (1 tick = 1 ms). Any other reply, such as an ack for an older hand-over,
 * is dropped. Returns 1 with *ack filled in, or 0 when the time is up. */
static uint8_t msc_wait_for_ack(JackReply_t *ack)
{
    uint32_t start_ms = osKernelGetTickCount();
    for (;;) {
        uint32_t waited_ms = osKernelGetTickCount() - start_ms;
        if (waited_ms >= MSC_ACK_TIMEOUT_MS) return 0U;
        if (osMessageQueueGet(s_replyQueue, ack, NULL, MSC_ACK_TIMEOUT_MS - waited_ms) != osOK) return 0U;
        if (msc_ack_matches(ack)) return 1U;
    }
}

/* The ack for the ENTER_MSC sent last has come, within the 2 s wait or
 * after it. ok 1: the card is the host's now, and MSC_Poll(), later in this
 * same loop pass, brings it up. ok 0: the storage task refused, so the card
 * stays hidden from the host until the cable is plugged in again. */
static void msc_take_ack(const JackReply_t *ack)
{
    if (!ack->ok) return;
    s_msc_active = 1U;
    s_msc_card_up = 0U;
}

/* Host attached: ask JackStorageTask for the card, then wait up to
 * MSC_ACK_TIMEOUT_MS for his ack. If it has not come by then (on a slow card
 * one step of his can take longer), it is still taken later: from now on
 * every loop pass looks for it (msc_poll_late_ack). */
static void msc_request_card(void)
{
    JackReply_t ack;
    (void)osMessageQueueReset(s_replyQueue);
    send_enter_msc(next_msc_seq());
    if (msc_wait_for_ack(&ack)) {
        msc_take_ack(&ack);
        return;
    }
    s_msc_ack_late = 1U;
}

/* While a late ack is awaited (once per loop pass, about LOOP_PERIOD_MS
 * apart): take it if it has come, with timeout 0, and drop any other reply.
 * s_replyQueue carries only ENTER_MSC acks (EXIT_MSC is sent without a
 * reply queue). */
static void msc_poll_late_ack(void)
{
    if (!s_msc_ack_late) return;
    JackReply_t r;
    while (osMessageQueueGet(s_replyQueue, &r, NULL, 0U) == osOK) {
        if (!msc_ack_matches(&r)) continue;     /* an older hand-over's ack: dropped */
        s_msc_ack_late = 0U;
        msc_take_ack(&r);
        return;
    }
}

/* USB watch -> MSC hand-over (spec section 7 "eject-to-use").
 *
 * The hand-over, step by step:
 *
 *   BrendonTask                                   JackStorageTask
 *   host attached (USB configured for 500 ms)
 *   ENTER_MSC, number n --jackCmdQueue-->         finishes its current step,
 *                                                 unmounts, gives up the card
 *   <--s_replyQueue-- JackReply_t {ENTER_MSC, ok, number n}
 *   s_msc_active = 1: MSC_Poll() brings the card up for the host
 *   ...
 *   host gone (500 ms)
 *   EXIT_MSC --jackCmdQueue-->                    mounts the card again
 *
 * BrendonTask waits up to MSC_ACK_TIMEOUT_MS (2 s) for the ack. On a slow
 * card Jack's current step (making an effect file, a delete, the first
 * folder on a card) can take longer, and an ack that came later used to be
 * lost: the PC then saw no card until the cable was plugged in again. Now
 * the ack is still taken on a later loop pass (s_msc_ack_late). Only the ack
 * with this hand-over's number counts: an ack for an older hand-over (the
 * host left and came back while Jack was still busy) is dropped, so
 * MSC_Poll() can never start while Jack is mounting the card again for the
 * EXIT_MSC in between (two tasks on the SDIO).
 *
 * Limit (rare): if the host leaves and comes back while Jack is still in
 * one long step (about 5 s or more), Jack answers the old and the new
 * ENTER_MSC one after the other. If this task has not taken the old ack in
 * between, the new ack finds s_replyQueue (1 deep) full and is lost. That
 * hand-over then runs without MSC_Poll() and without the Transfer aborted
 * check below until the host leaves: the PC still gets the card if Jack
 * had it mounted, but not a card inserted later.
 *
 *   state                event                          next state
 *   idle                 host attached: ENTER_MSC n     waiting (up to 2 s)
 *   waiting              ack n, ok 1                    MSC active
 *   waiting              ack n, ok 0 (refused)          idle, card hidden
 *   waiting              2 s up                         late wait
 *   late wait            ack n, ok 1                    MSC active ("late ack")
 *   late wait            ack n, ok 0 (refused)          idle, card hidden
 *   late wait or active  host gone: EXIT_MSC            idle
 *   any                  an ack with another number     (dropped)
 *
 * Transfer aborted (fault screen, PD2 2.21): FatFs cannot see a FAT32
 * "dirty" flag, so "the host wrote to the card during this hand-over and
 * left without ejecting it" is the sign that a copy may have been cut off.
 * The eject state lives in the MSC class data (SCSI START STOP UNIT sets
 * scsi_medium_state). It is copied here on every loop pass while the card is
 * the host's, because the class data is released (pClassData = NULL) when
 * the USB stack stops, which can happen before the host-gone debounce below
 * has finished. Reading it is a byte read of the USB device state this task
 * owns; the buffer behind it is static (USBD_static_malloc), never freed. */
static void usb_watch(uint32_t now)
{
    msc_poll_late_ack();                        /* an ENTER_MSC ack that came after the 2 s wait */

    if (s_msc_active) {
        const USBD_MSC_BOT_HandleTypeDef *msc = (const USBD_MSC_BOT_HandleTypeDef *)hUsbDeviceFS.pClassData;
        if (msc != NULL) s_msc_ejected = (msc->scsi_medium_state == SCSI_MEDIUM_EJECTED) ? 1U : 0U;
    }

    /* 500 ms debounce: "configured" (the PC has finished setting us up) must
     * hold for USB_DEBOUNCE_MS before it counts, and so must its loss. While
     * a PC sets us up, or resets the bus, the state is something else for a
     * moment, and every hand-over makes Jack unmount and later re-mount the
     * card: a blip must not start one. */
    uint8_t raw = (hUsbDeviceFS.dev_state == USBD_STATE_CONFIGURED) ? 1U : 0U;
    if (raw != s_usb_raw_prev) {
        s_usb_raw_prev = raw;
        s_usb_change_ms = now;
        return;
    }
    if (raw == s_usb_configured) return;
    if ((now - s_usb_change_ms) < USB_DEBOUNCE_MS) return;
    s_usb_configured = raw;

    /* Why hand the card over at all: FatFs (Jack) and the PC's own file
     * system each keep part of the card (FAT, folders, free space) in RAM
     * and know nothing of each other, so if both used it they would undo
     * each other's changes and corrupt it. Jack unmounts first (ENTER_MSC)
     * and mounts again only after the PC has gone (EXIT_MSC), reading the
     * card afresh. */
    if (s_usb_configured) {
        /* Zeroed BEFORE the hand-over: until Jack sets g_msc_media_ready the
         * host's writes are refused, so none can be lost by this reset. */
        g_msc_host_writes = 0U;
        s_msc_ejected = 0U;
        msc_request_card();
    } else {
        if (s_msc_active && g_msc_host_writes > 0U && !s_msc_ejected) {
            App_RTOS_RaiseFault(FAULT_SRC_USB, FAULT_USB_ABORTED, "Transfer aborted", "Card re-mounted");
        }
        /* Stop waiting for a late ack: Jack takes the ENTER_MSC and then this
         * EXIT_MSC in order, so the card ends up mounted by him again. */
        s_msc_ack_late = 0U;
        send_exit_msc();
        s_msc_active = 0U;
        s_msc_card_up = 0U;
        if (s_usb_running) s_usb_host_left = 1U;   /* usb_gate, called next, stops the stack: PA9 is then judged with D+ released */
    }
}

/* USB gate: start the stack on a debounced VBUS_SENSE high, stop it on a
 * debounced low, when the host leaves, or after USB_NO_HOST_MS without a
 * configured host (see s_usb_running). Stopping takes the D+ pull-up off the
 * bus and turns the OTG_FS clock off; a restart then waits USB_RESTART_HOLD_MS
 * and needs PA9 still high with nothing of ours on the net. With a charge-only
 * supply (or a sleeping PC) this re-checks every ~4.5 s. */
static void usb_stop(uint32_t now)
{
    (void)USBD_DeInit(&hUsbDeviceFS);
    s_usb_running = 0U;
    s_usb_host_left = 0U;
    s_usb_hold_until = now + USB_RESTART_HOLD_MS;
}

static void usb_gate(uint32_t now)
{
    uint8_t vbus = Charger_IsVbusPresent(&s_chg);
    if (vbus != s_vbus_raw_prev) {
        s_vbus_raw_prev = vbus;
        s_vbus_change_ms = now;
    }
    uint8_t stable = ((now - s_vbus_change_ms) >= VBUS_DEBOUNCE_MS) ? 1U : 0U;

    if (s_usb_running) {
        if (hUsbDeviceFS.dev_state == USBD_STATE_CONFIGURED) {
            s_usb_host_seen_ms = now;
        }
        /* Three reasons to stop: VBUS has gone; the host has left (PA9 is
         * then re-checked with D+ released); or no host has configured us
         * for USB_NO_HOST_MS (PA9 is re-checked the same way). */
        if ((stable && !vbus) || s_usb_host_left ||
            (now - s_usb_host_seen_ms) >= USB_NO_HOST_MS) {
            usb_stop(now);
        }
    } else if (stable && vbus && (int32_t)(now - s_usb_hold_until) >= 0) {
        MX_USB_DEVICE_Init();               /* VBUS present: start the USB stack */
        s_usb_running = 1U;
        s_usb_host_seen_ms = now;
    }
}

/* --------------------------------- API ---------------------------------- */
/* Called by main() BEFORE the kernel starts: no queue, flag or task exists
 * yet, so the gauge probe here takes the blocking I2C path (brendon_ports.c). */
void Brendon_Init(I2C_HandleTypeDef *hi2c)
{
    BrendonPorts_Init(hi2c);
    HAL_Delay(50);                      /* pre-kernel: gauge power-up settle */
    /* A missing gauge is not an error here: BrendonTask reports it on the
     * fault screen once and looks for it again every 5 s. */
    (void)BatMon_Init(&s_mon, BrendonPorts_BqBus());
    (void)Charger_Init(&s_chg, BrendonPorts_ChargerPins());
    BatTime_Init(&s_time);              /* empty: the first publish starts the average */
}

void Brendon_TaskEntry(void *argument)
{
    (void)argument;

    const osMessageQueueAttr_t ra = { .name = "brendonReply" };
    s_replyQueue = osMessageQueueNew(1U, sizeof(JackReply_t), &ra);

    uint32_t next_charger = osKernelGetTickCount();
    uint32_t next_power_debug = osKernelGetTickCount();   /* first one on the first loop pass */
    uint32_t next_gauge_retry = osKernelGetTickCount() + GAUGE_RETRY_MS;
    if (!BatMon_GaugePresent(&s_mon)) {
        /* Fault screen, once per boot: the 5 s re-probes below stay quiet. */
        App_RTOS_RaiseFault(FAULT_SRC_BATTERY, FAULT_BAT_GAUGE_MISSING, "Gauge not found", "Battery info off");
    }
    battery_publish();                  /* first snapshot straight away */

    for (;;) {
        /* The task's one regular wait: sleep LOOP_PERIOD_MS, so TonyTask
         * (lower priority) and the idle task get the CPU between passes. */
        osDelay(LOOP_PERIOD_MS);

        uint32_t now = osKernelGetTickCount();
        if (!BatMon_GaugePresent(&s_mon) && (int32_t)(now - next_gauge_retry) >= 0) {
            /* Gauge absent at boot (late power-up, loose I2C): re-probe it. On
             * success BatMon_Tick below polls and publishes straight away. */
            next_gauge_retry = now + GAUGE_RETRY_MS;
            (void)BatMon_RetryProbe(&s_mon);
        }
        brendon_cmd_drain(now);                   /* debug screen: before the tick, see brendon_cmd_drain */
        /* Why 1 Hz: a battery's charge changes slowly, so once a second is
         * plenty for the status bar and the alarms, and one poll is only 8
         * short gauge reads (5 core + 3 extras, battery_monitor.c). */
        if (BatMon_Tick(&s_mon, now)) {           /* 1 Hz, driven by the tick we pass in */
            battery_publish();
        }
        if ((int32_t)(now - next_charger) >= 0) {
            (void)Charger_Tick(&s_chg, now);       /* 10 Hz so the 1 Hz fault blink is seen */
            next_charger = now + CHARGER_POLL_MS;
        }
        usb_watch(now);                            /* first: a "PC gone" seen here is acted on by usb_gate below */
        usb_gate(now);
        if (s_msc_active && s_msc_card_up &&
            (HAL_GPIO_ReadPin(SD_DETECT_GPIO_Port, SD_DETECT_Pin) == GPIO_PIN_SET ||
             (hsd.ErrorCode & (HAL_SD_ERROR_CMD_RSP_TIMEOUT | HAL_SD_ERROR_DATA_TIMEOUT)) != 0U)) {
            /* Card pulled while the host had it: SD_DETECT reads high (active-
             * low switch, 0 V = card) or the host's last command/transfer
             * (issued from the OTG_FS interrupt) got no answer. Re-arm the
             * bring-up so a re-inserted card is initialised again (MSC_Poll
             * rate-limits the attempts to one per 500 ms). Neither check puts
             * anything on the bus. */
            hsd.ErrorCode = HAL_SD_ERROR_NONE;
            s_msc_card_up = 0U;
        }
        if (s_msc_active && !s_msc_card_up) {
            /* Bring the card up for the host ONCE per hand-over (usually it is
             * already initialised by Jack's mount and this returns MSC_OK at
             * once). Afterwards the OTG_FS ISR does raw block I/O on the SDIO;
             * a CMD13 from here would interleave with that on the same bus. */
            if (MSC_Poll(BrendonPorts_MscStore(), HAL_GetTick()) == MSC_OK) {
                s_msc_card_up = 1U;
            }
        }
        if ((int32_t)(now - next_power_debug) >= 0) {
            power_debug_publish(now);              /* 1 Hz, gauge present or not */
            next_power_debug = now + POWER_DEBUG_MS;
        }
    }
}

void Brendon_GetSnapshot(Battery_Snapshot_t *out)   { BatMon_GetSnapshot(&s_mon, out); }
uint8_t Brendon_IsLowBattery(void)                  { return BatMon_IsLowBattery(&s_mon); }
uint8_t Brendon_IsCriticalBattery(void)             { return BatMon_IsCriticalBattery(&s_mon); }
